import { Compass, Move, Play, ZoomIn } from 'lucide-react';
import { useNavigate, useParams } from 'react-router-dom';
import { useMuseumConfig } from '../../config/ConfigProvider';
import { MapPage as MapStage } from '../../features/map/MapPage';
import '../next-map.css';

/**
 * 地图页（新壳）。
 *
 * 地图本体的功能全部由共享的 `features/map/MapPage.tsx` 承担——引擎（`useMapEngine`）、
 * 瓦片（`useMapTiles` + `TileImage`）、拖拽/双指缩放/双击放大、标记拾取写回配置、
 * 隐藏的地图设置抽屉、进入全景的幕布与漫游层都在里面，一条不少。
 * 这里只叠一层 Concept A 的壳：点位详情卡 + 手势提示条。
 *
 * 为什么不自己重画一遍舞台：那 543 行里有大量"看起来多余、其实是踩过的坑"的注释
 * （布局像素缩放、瓦片缝隙取整、主源重试切备用源、进入动画时长），复制一份等于把坑复制两遍。
 */
export function MapPage({ active = true }: { active?: boolean } = {}) {
  const { config } = useMuseumConfig();
  const { mapId, pointId } = useParams();
  const navigate = useNavigate();

  const map = config.maps.find(item => item.id === mapId) ?? config.maps[0];
  const point = map?.points[0];
  const panorama = point?.target.kind === 'panorama'
    ? config.panoramas.find(item => item.id === point.target.id)
    : undefined;
  // 漫游路由下，地图页会渲染整屏的全景层；这层 chrome 必须让开，否则会压在全景上。
  const roaming = Boolean(pointId);

  return (
    <section className="next-map">
      <MapStage active={active} />
      {!roaming && point && map && (
        <div className="next-map-chrome">
          <article className="next-map-card">
            <span className="next-pill">全景漫游</span>
            <h2>{point.label}</h2>
            <p>{point.description ?? panorama?.description ?? ''}</p>
            <button
              type="button"
              className="next-primary"
              onClick={() => navigate(`/map/${map.id}/roam/${point.id}`)}
            >
              进入全景漫游
            </button>
          </article>
          <ul className="next-map-dock" aria-label="地图操作提示">
            <li><Move aria-hidden="true" />拖动平移</li>
            <li><ZoomIn aria-hidden="true" />双击放大</li>
            <li><Compass aria-hidden="true" />双指缩放</li>
            <li><Play aria-hidden="true" />点标记进入</li>
          </ul>
        </div>
      )}
    </section>
  );
}

export default MapPage;
